"""Render `reports/03-bounds.md` from the Stage 3 artifact.

Every number is read from `data/derived/03-bounds.json`, which the Stage 3 gate
asserts against, so the reader and the gate cannot disagree.
"""

from __future__ import annotations

from pathlib import Path

from . import caveat
from . import config as C
from .report import _km, _pct, _table
from .report02 import _block, _f, _h, _n


def write(a: dict, path: Path = C.BOUNDS_REPORT_MD) -> Path:
    parts = ["# Stage 3 — bounds, and the first real deadhead number\n"]
    parts.append(
        "Generated by `efficientroute stage3`. Every number below is read from\n"
        "`data/derived/03-bounds.json`, which the Stage 3 gate asserts against."
    )
    parts.append(_headline(a))
    parts.append(_transform(a))
    parts.append(_upper(a))
    parts.append(_lower(a))
    parts.append(_gap(a))
    parts.append(_variants(a))
    parts.append(_stage2(a))
    parts.append(_scope(a))
    parts.append(_spec(a))
    parts.append(_gate(a))

    path.parent.mkdir(parents=True, exist_ok=True)
    caveat.write(path, _block(*parts))
    return path


def _by_variant(a: dict) -> dict:
    return {row["variant"]: row for row in a["variants"]}


# --------------------------------------------------------------------- headline


def _headline(a: dict) -> str:
    A = _by_variant(a)["A"]
    day = a["day"]
    return (
        "\n## Headline\n\n"
        f"> ## The optimum lies between **{_h(A['lower_bound_h'])} h** and "
        f"**{_h(A['total_h'])} h**\n"
        f">\n"
        f"> Variant A, the network as built. The upper end is not an estimate: it is a\n"
        f"> **real closed tour** of {_n(A['arc_traversals'])} arc traversals that drives every\n"
        f"> reachable required element at least as often as required, turns only where the\n"
        f"> law allows, and returns to where it started.\n"
        f">\n"
        f"> **Deadhead is {_h(A['deadhead_h'])} h — {_pct(A['deadhead_pct_of_capture'])} of capture\n"
        f"> time**, {_pct(A['deadhead_pct_of_total'])} of the tour. That is the number Stage 2\n"
        f"> could not produce and the one the A/D/C scope decision needs.\n"
        f">\n"
        f"> Optimality gap: **{_pct(A['optimality_gap'] * 100)}**.\n"
        "\n"
        f"At {_f(day['productive_hours'], 2)} productive hours a day that is\n"
        f"**{_h(A['days'])} days** of driving before depot legs — which Stage 3 does not\n"
        "model, and §7 says so plainly.\n"
    )


# -------------------------------------------------------------------- item 1


def _transform(a: dict) -> str:
    A = _by_variant(a)["A"]
    return (
        "\n## 1. The node-split transform, `L → L*`\n\n"
        "`L(G)` has **nodes** that must be visited. Postman problems are defined over\n"
        "**edges**. Every arc-routing formulation that tries to cover nodes directly is\n"
        "solving a different problem than the one it thinks it is, so the split comes first\n"
        "and everything else is built on top of it.\n\n"
        "```\n"
        "a_in ──[ capture:  lower = upper = min_passes(a), cost = capture_time_s(a) ]──▶ a_out\n"
        "     └─[ deadhead: lower = 0,        upper = ∞,   cost = deadhead_time_s(a) ]─┘\n"
        "\n"
        "a_out ──[ manoeuvre a → b: cost = turn penalty ]──▶ b_in\n"
        "```\n\n"
        "\"Cover arc `a` at least `k` times\" is now exactly \"traverse the required edge\n"
        "`(a_in, a_out)` `k` times\" — a Directed Chinese Postman with lower bounds, which\n"
        "min-cost flow with lower bounds solves exactly.\n\n"
        "**Two edges, not one.** The stage brief describes a single required edge at\n"
        "`capture_time_s`. SPEC §6 is more specific: the 40 km/h cap binds on *required*\n"
        "traversals and \"deadhead segments are uncapped\". A repeat pass that no requirement\n"
        "asked for is a deadhead segment, so it is priced at the uncapped speed. Splitting\n"
        "the edge is the only way to charge the two kinds of traversal differently, and\n"
        "because `deadhead_time_s ≤ capture_time_s` always, the flow uses the capture edge\n"
        "exactly `min_passes` times without being told to.\n\n"
        + _table(
            ["Measure", "Variant A"],
            [
                ["Nodes of L (directed arcs)", _n(A["l_nodes"])],
                ["Nodes of L*", _n(A["l_star_nodes"])],
                ["Legal manoeuvres", _n(A["l_star_manoeuvres"])],
                ["Edges of L*", _n(A["l_star_edges"])],
                ["L-nodes a closed tour can reach", _n(A["l_nodes_tourable"])],
            ],
        )
        + "\n\nCosts are discretised to integer **milliseconds** for the flow solver, which needs\n"
        "integers. Every hour reported here is recomputed in floating point from the tour\n"
        "itself, so the discretisation never reaches a number a reader sees.\n"
    )


# -------------------------------------------------------------------- item 2


def _upper(a: dict) -> str:
    A = _by_variant(a)["A"]
    orientation = A["orientation"]
    flow = A["flow"]

    parts = ["\n## 2. The constructive upper bound — a real plan\n"]
    parts.append(
        "Three steps: orient the narrow pairs, solve the Chinese Postman exactly for that\n"
        "orientation, extract an Euler circuit. The result is a complete, legal, closed\n"
        "single tour of Tbilisi.\n"
    )

    parts.append("\n### 2.1 Orienting the narrow pairs\n")
    parts.append(
        "SPEC §2.1 gives a narrow two-way street a requirement of **one** traversal from\n"
        "either direction. Fixing which direction removes the generalisation and leaves an\n"
        "ordinary Directed Chinese Postman — at the cost of making the answer an upper bound.\n"
        "\n**Where the imbalance lives.** It is tempting to minimise imbalance on `L*`, and it\n"
        "would be wasted work: imbalance there is *orientation-invariant*. Every required\n"
        "edge `a_in → a_out` creates exactly one unit of source and one of sink, and a pair\n"
        "contributes exactly one required edge whichever way it is turned, so\n"
        "`Σ|supply| = 2·Σ lower` regardless. The choice only moves *where* the sources and\n"
        "sinks are. The quantity that does respond is imbalance at the **base network's\n"
        "junctions**, which is what SPEC §4 means and what the heuristic minimises.\n"
    )
    parts.append(
        _table(
            ["Measure", "Value"],
            [
                ["Narrow pairs", _n(orientation["pair_count"])],
                ["Junction imbalance, naive orientation", _n(orientation["imbalance_naive"])],
                ["…after the greedy pass", _n(orientation["imbalance_after_greedy"])],
                ["**…after local search**", f"**{_n(orientation['imbalance_after'])}**"],
                ["Flips: greedy / local search",
                 f"{_n(orientation['flips_greedy'])} / {_n(orientation['flips_local_search'])}"],
                ["Local-search passes to converge", _n(orientation["local_search_passes"])],
                ["Pairs with only one drivable direction (forced)",
                 _n(orientation["forced_pairs"])],
                ["Pairs with neither direction reachable", _n(orientation["unreachable_pairs"])],
                ["Degenerate pairs (both ends the same junction)",
                 _n(orientation["degenerate_pairs"])],
            ],
        )
    )
    parts.append(
        f"\nThe heuristic removes {_pct((1 - orientation['imbalance_after'] / orientation['imbalance_naive']) * 100)}\n"
        "of the junction imbalance. That is a modest gain and it is worth saying so: most of\n"
        "Tbilisi's imbalance is structural — one-way streets and dead ends — and no choice\n"
        "of pair direction can remove it.\n"
    )

    parts.append("\n### 2.2 Balancing, and the part that is actually NP-hard\n")
    parts.append(
        "Min-cost flow with lower bounds balances every node of `L*` exactly and in\n"
        "polynomial time. **Connectivity is the hard half.** Only some edges are required —\n"
        "the unoriented half of every narrow pair is free, and so is every manoeuvre — so\n"
        "the cheapest circulation is free to fall into many separately-balanced pieces, each\n"
        "internally Eulerian and mutually unreachable. There is no single circuit over that.\n"
        "\nTbilisi does exactly this, and the mechanism is a dead-end two-way street: the\n"
        "cheapest way to satisfy its one required traversal is to drive in, turn at the tip,\n"
        "and turn straight back in again — a self-contained two-cycle that touches nothing\n"
        "else and is perfectly balanced. The flow finds thousands of them.\n"
    )
    parts.append(
        _table(
            ["Measure", "Value"],
            [
                ["Components in the first circulation", _n(flow["components_initial"])],
                ["Nodes stranded outside the main one", _n(flow["stranded_nodes"])],
                ["Repair rounds to reach one component", _n(flow["connect_rounds"])],
                ["Edges forced to connect them", _n(flow["forced_edges"])],
                ["**Balance cost** (the flow optimum)", f"**{_h(flow['balance_cost_s'] / 3600)} h**"],
                ["**Connectivity cost** (the repair)",
                 f"**{_h(flow['connectivity_cost_s'] / 3600)} h**"],
            ],
        )
    )
    parts.append(
        f"\nThe repair costs {_h(flow['connectivity_cost_s'] / 3600)} h — "
        f"{_pct(flow['connectivity_cost_s'] / flow['total_cost_s'] * 100)} of the tour. It is a\n"
        "heuristic (force a cheapest entry into each stranded piece, then re-solve and let\n"
        "the flow find its own way back out), so a better one would produce a cheaper tour.\n"
        "It is charged separately above rather than folded into the total, because it is the\n"
        "one part of the constructive result that is *not* exact.\n"
    )

    parts.append("\n### 2.3 The tour\n")
    parts.append(
        _table(
            ["Measure", "Variant A"],
            [
                ["Arc traversals", _n(A["arc_traversals"])],
                ["Driven km", _km(A["driven_km"])],
                ["Required km (reachable)", _km(A["required_km_in_scope"])],
                ["**Capture time**", f"**{_h(A['capture_h'])} h**"],
                ["**Deadhead time**", f"**{_h(A['deadhead_h'])} h**"],
                ["**Turn time**", f"**{_h(A['turn_h'])} h**"],
                ["**Total**", f"**{_h(A['total_h'])} h**"],
            ],
        )
    )
    parts.append(
        f"\n> **`deadhead_ratio = (total − capture − turn) / capture` = "
        f"{A['deadhead_h'] / A['capture_h']:.3f}** — "
        f"{_pct(A['deadhead_pct_of_capture'])}.\n"
        f">\n"
        f"> By distance, SPEC §9's form `(driven − required)/required` gives\n"
        f"> **{A['km_deadhead_ratio']:.3f}**. The two differ because deadhead runs uncapped and\n"
        f"> is therefore faster per kilometre than capture.\n"
        "\nSPEC §4's KPI warning applies in full: the hybrid coverage rule *deliberately*\n"
        "raises this ratio. **Total driving hours is the KPI**, and a scope variant that\n"
        "lowers the ratio while raising the hours is the wrong choice.\n"
    )
    return _block(*parts)


# -------------------------------------------------------------------- item 3


def _lower(a: dict) -> str:
    A = _by_variant(a)["A"]
    lp = A["lower_bound_lp"]
    fallback = A["lower_bound_fallback"]

    parts = ["\n## 3. The genuine lower bound\n"]
    parts.append(
        "Fixing an orientation *adds* a constraint, so §2's tour cannot bound from below —\n"
        "it is a feasible solution, and feasible solutions bound from above. The bound is\n"
        "computed separately, from a relaxation of the generalised routing problem over `L*`:\n"
        "\n- integrality dropped — traversal counts go continuous;\n"
        "- the orientation choice returned — each narrow pair carries one\n"
        "  `y_a + y_b ≥ 1` row instead of a fixed direction;\n"
        "- connectivity dropped entirely.\n"
        "\nAll three make it a genuine relaxation, and therefore genuinely below the optimum.\n"
    )
    parts.append(
        _table(
            ["Method", "Bound", "Status", "Runtime"],
            [
                [
                    "**LP relaxation** (used)",
                    f"**{_h(lp['lower_bound_h'])} h**",
                    lp["status"],
                    f"{_f(lp['runtime_s'], 0)} s",
                ],
                [
                    "Capture floor + cheapest exit (fallback)",
                    f"{_h(fallback['lower_bound_h'])} h",
                    fallback["status"],
                    f"{_f(fallback['runtime_s'], 1)} s",
                ],
            ],
        )
    )
    parts.append(
        f"\nThe LP is {_n(lp.get('columns', 0))} columns and {_n(lp.get('rows', 0))} rows\n"
        f"({_n(lp.get('nonzeros', 0))} nonzeros), of which {_n(lp.get('pair_rows', 0))} rows are\n"
        "the narrow-pair disjunctions that stop it being a pure network LP. Solved with HiGHS\n"
        "interior point, single-threaded and seeded so the bound does not wobble between runs.\n"
        "\nThe fallback is reported alongside rather than discarded: it is rigorous, it costs a\n"
        "second, and an LP that fell *below* it would be solving a different model. It is\n"
        "weak because it accounts for no repositioning at all — every required traversal, plus\n"
        "the cheapest legal way to leave it, and nothing else.\n"
    )
    return _block(*parts)


def _gap(a: dict) -> str:
    A = _by_variant(a)["A"]
    flow = A["flow"]
    lower = A["lower_bound_h"]
    balance = flow["balance_cost_s"] / 3600.0
    total = A["total_h"]

    return _block(
        "\n## 4. Where the gap comes from\n",
        f"The gap is **{_pct(A['optimality_gap'] * 100)}**, which is wide. It is worth being\n"
        "precise about which side of it is loose, because the answer decides what Stage 5\n"
        "should work on.\n",
        _table(
            ["Step", "Hours", "Δ", "What it costs"],
            [
                ["LP relaxation (lower bound)", _h(lower), "—",
                 "fractional coverage, free orientation, no connectivity"],
                ["Min-cost flow, one fixed orientation", _h(balance),
                 f"+{_h(balance - lower)}", "integrality and the orientation choice"],
                ["**Constructive tour** (upper bound)", f"**{_h(total)}**",
                 f"+{_h(total - balance)}", "connectivity repair"],
            ],
        ),
        f"**Almost all of the gap is bound looseness, not tour slack.** Going from the LP to an\n"
        f"integral single-orientation circulation costs {_h(balance - lower)} h; making that\n"
        f"circulation into one connected tour costs {_h(total - balance)} h. The tour is close\n"
        "to optimal *for its orientation* — the flow solving that part is exact — and the LP\n"
        "is far below any integral solution because it is free to cover half of one direction\n"
        "of a narrow pair and half of the other.\n",
        "Two consequences worth carrying into Stage 5:\n"
        "\n"
        "- **Do not read the gap as slack to be recovered by better routing.** Most of it\n"
        "  cannot be reached by any feasible tour.\n"
        "- **The orientation heuristic is the lever that matters**, not the deadhead routing.\n"
        f"  It removed only {_pct((1 - A['orientation']['imbalance_after'] / A['orientation']['imbalance_naive']) * 100)}\n"
        "  of junction imbalance; SPEC §4 Stage D's orientation-flip local search is aimed at\n"
        "  exactly this and has not been run here.\n",
    )


# -------------------------------------------------------------------- item 4


def _variants(a: dict) -> str:
    day = a["day"]
    parts = ["\n## 5. The A / D / C table\n"]
    parts.append(
        f"`days = total_hours / productive_hours_per_day`, with\n"
        f"**`productive_hours_per_day` = {_f(day['productive_hours'], 2)} h** — the Stage 2\n"
        f"shift of {_f(day['shift_hours'], 1)} h net of the {_f(day['break_hours'], 2)} h break\n"
        "and nothing else. Stage 3 models no depot legs (§7), so no leg time is subtracted.\n"
    )
    rows = []
    for row in a["variants"]:
        rows.append(
            [
                f"**{row['variant']}**",
                _h(row["capture_h"]),
                _h(row["turn_h"]),
                _h(row["deadhead_h"]),
                _pct(row["deadhead_pct_of_capture"]),
                _h(row["total_h"]),
                _h(row["lower_bound_h"]),
                _pct(row["optimality_gap"] * 100),
                _h(row["days"]),
            ]
        )
    parts.append(
        _table(
            ["Variant", "Capture h", "Turn h", "Deadhead h", "Deadhead %",
             "Total h", "Lower bound h", "Gap %", "Days"],
            rows,
        )
    )
    labels = {row["variant"]: row["label"] for row in a["variants"]}
    parts.append(
        "\n"
        + "\n".join(f"- **{key}** — {value}" for key, value in labels.items())
    )

    A = _by_variant(a)["A"]
    D = _by_variant(a)["D"]
    Cv = _by_variant(a)["C"]
    parts.append(
        f"\n**The scope question, answered in hours with deadhead counted.** Dropping `spur`\n"
        f"and `orphan` service roads (**D**) saves {_h(A['total_h'] - D['total_h'])} h —\n"
        f"{_pct((1 - D['total_h'] / A['total_h']) * 100)} of the campaign, or\n"
        f"{_h(A['days'] - D['days'])} days — while keeping every service road that actually\n"
        f"links two streets. Dropping service entirely (**C**) saves\n"
        f"{_h(A['total_h'] - Cv['total_h'])} h.\n"
        f"\nNote what the deadhead column does: it is\n"
        f"{_pct(A['deadhead_pct_of_capture'])} for A and {_pct(D['deadhead_pct_of_capture'])}\n"
        f"for D. Spurs are dead ends, and a dead end is driven in and back out, so the arcs D\n"
        "removes are the ones carrying the *worst* deadhead. That is the KPI warning in SPEC\n"
        "§4 working in reverse — and it is still not a reason to choose D. **Total hours is\n"
        "the KPI**, and D wins on hours too.\n"
        "\n**Stage 3 does not choose.** SPEC §1.1 makes inclusion the default and the stage\n"
        "non-goals are explicit. Stage 4 makes the call with this table in hand.\n"
    )

    parts.append("\n### 5.1 A 10-hour shift window (08:00–18:00)\n")
    parts.append(
        "The cheapest schedule lever available, and one that needs quantifying rather than\n"
        "guessing. SPEC §7.2 already argues the outbound leg wants to be earlier, and SPEC\n"
        "§7.3 puts sunset well clear of 18:00 until November, so the extra hour goes at the\n"
        "front of the day.\n"
    )
    rows = []
    for row in a["variants"]:
        rows.append(
            [
                f"**{row['variant']}**",
                _h(row["total_h"]),
                _h(row["days"]),
                _h(row["days_extended_shift"]),
                f"−{_h(row['days'] - row['days_extended_shift'])}",
                _pct((1 - row["days_extended_shift"] / row["days"]) * 100),
            ]
        )
    parts.append(
        _table(
            ["Variant", "Total h",
             f"Days @ {_f(day['productive_hours'], 2)} h",
             f"Days @ {_f(day['extended_productive_hours'], 2)} h",
             "Δ days", "Saving"],
            rows,
        )
    )
    A_saving = (1 - _by_variant(a)["A"]["days_extended_shift"] / _by_variant(a)["A"]["days"]) * 100
    parts.append(
        f"\nOne extra hour a day removes {_pct(A_saving)} of the campaign — "
        f"{_h(_by_variant(a)['A']['days'] - _by_variant(a)['A']['days_extended_shift'])} days on\n"
        "variant A — for no change to the plan and no new risk beyond an earlier start.\n"
        "\nThe scope decision in §5 is worth more (variant D saves\n"
        f"{_pct((1 - _by_variant(a)['D']['total_h'] / _by_variant(a)['A']['total_h']) * 100)}), but it\n"
        "buys that by capturing less. **This is the largest saving available without changing\n"
        "what gets captured**, and the two compose: D on a 10-hour shift needs\n"
        f"{_h(_by_variant(a)['D']['days_extended_shift'])} days against variant A's\n"
        f"{_h(_by_variant(a)['A']['days'])} as built.\n"
    )
    return _block(*parts)


def _stage2(a: dict) -> str:
    """What Stage 2 said, what it could not say, and what happened."""
    stage2 = a.get("stage2")
    if not stage2:
        return ""
    A = _by_variant(a)["A"]
    prior = stage2["variants"]["A"]
    window = stage2["daylight_window_days"]

    parts = ["\n## 6. Against Stage 2\n"]
    parts.append(
        "Stage 2 estimated capture and turn time and said, in those words, that it was a\n"
        "**floor**: it counted no deadhead because no measurement stood behind one. Stage 3\n"
        "supplies that term, so the two belong side by side.\n"
    )
    parts.append(
        _table(
            ["Term", "Stage 2 (variant A)", "Stage 3 (variant A)", "Δ"],
            [
                ["Capture h", _h(stage2["capture_hours_free_flow"]), _h(A["capture_h"]),
                 f"{A['capture_h'] - stage2['capture_hours_free_flow']:+.1f}"],
                ["Turn h", _h(stage2["turn_hours_estimate"]), _h(A["turn_h"]),
                 f"{A['turn_h'] - stage2['turn_hours_estimate']:+.1f}"],
                ["Deadhead h", "*not estimated*", _h(A["deadhead_h"]), "—"],
                ["**Total h**", f"**{_h(stage2['capture_hours_free_flow'] + stage2['turn_hours_estimate'])}**",
                 f"**{_h(A['total_h'])}**",
                 f"**+{_h(A['total_h'] - stage2['capture_hours_free_flow'] - stage2['turn_hours_estimate'])}**"],
            ],
        )
    )
    parts.append(
        f"\nBoth stages price capture at free flow, so the capture line differs only because\n"
        f"{_km(A['required_km_out_of_scope'])} km of required traversal is not reachable by any\n"
        f"closed tour — {_km(A['required_km_absent_from_l'])} km that never entered `L(G)` and\n"
        f"{_km(A['required_km_trapped_in_l'])} km of legal traps inside it (§7.1).\n"
        f"\n**The turn line is the interesting one.** Stage 2 flagged its turn account as the\n"
        f"model's largest uncertainty, ranging {_h(stage2['turn_hours_floor'])}–"
        f"{_h(stage2['turn_hours_estimate'])} h. The tour spends {_h(A['turn_h'])} h — *above*\n"
        "the top of that range. Stage 2 was not wrong about the per-traversal cost; the tour\n"
        f"in fact averages {A['turn_h'] * 3600 / A['arc_traversals']:.2f} s per exit against\n"
        "Stage 2's assumed 5.39 s. It is above the range because Stage 2 could only count\n"
        f"turns on *required* traversals, and the tour makes {_n(A['arc_traversals'])} of them\n"
        "in total. **Deadhead traversals turn corners too** — a term no capture-only estimate\n"
        "can see, and worth carrying into any future floor.\n"
    )

    parts.append("\n### 6.1 The daylight window, now decidable\n")
    parts.append(
        f"Stage 2 §5.4 established a **{_n(window)}-day window** from "
        f"{stage2['campaign_start']} to {stage2['daylight_binding_date']}, the date SPEC §7.3\n"
        "puts sunset below the 18:00 shift end, and could express the risk only as a\n"
        "question: how much deadhead would fit? Variant A's answer was\n"
        f"{_pct(stage2['deadhead_headroom']['A'] * 100)}. The measured deadhead ratio is\n"
        f"**{_pct(A['deadhead_pct_of_capture'])}**.\n"
    )
    rows = []
    for row in a["variants"]:
        headroom = stage2["deadhead_headroom"].get(row["variant"])
        rows.append(
            [
                f"**{row['variant']}**",
                _pct(headroom * 100) if headroom is not None else "—",
                _pct(row["deadhead_pct_of_capture"]),
                _h(row["days"]),
                _h(row["days_extended_shift"]),
                "yes" if row["days"] <= window else "**no**",
                "yes" if row["days_extended_shift"] <= window else "**no**",
            ]
        )
    parts.append(
        _table(
            ["Variant", "Deadhead Stage 2 could absorb", "Deadhead measured",
             "Days @ 9 h", "Days @ 10 h", "Inside window @ 9 h", "@ 10 h"],
            rows,
        )
    )
    A_days = A["days"]
    parts.append(
        f"\n**Finding: variant A does not fit the daylight window at either shift length.**\n"
        f"It needs {_h(A_days)} days at a 9-hour shift and "
        f"{_h(A['days_extended_shift'])} at a 10-hour one, against {_n(window)} available —\n"
        "and that is *before* depot legs, which Stage 3 does not model and which Stage 2\n"
        "measured at roughly a tenth of the campaign. Variant D fits at both.\n"
        "\nSPEC §7.3's condition — \"if the estimate pushes the finish past October, revisit the\n"
        "shift window rather than accepting degraded final hours\" — is now met on evidence\n"
        "rather than on an estimate. The levers, in the order SPEC already ranks them, are:\n"
        "capture on the commute (§7.1), the scope decision (§5), the extended shift (§5.1),\n"
        "and far-zones-first sequencing. **Stage 3 does not pull any of them** — it reports\n"
        "that at least one is now required.\n"
    )
    return _block(*parts)


# ------------------------------------------------------------------- scope


def _scope(a: dict) -> str:
    parts = ["\n## 7. What this tour is not\n"]
    parts.append(
        "**It is not a day plan and must not be presented as one.** It is one closed circuit\n"
        "of the entire city with no depot legs, no day boundaries and no breaks. `reports/`\n"
        "carries it as GPX so that it can be opened in a mapping tool and looked at — a\n"
        "sanity check on the solver, not a schedule. Zoning is Stage 4 and day assembly is\n"
        "Stage 5.\n"
    )
    rows = []
    for row in a["variants"]:
        rows.append(
            [
                f"**{row['variant']}**",
                _km(row["required_km_total"]),
                _km(row["required_km_in_scope"]),
                _km(row["required_km_out_of_scope"]),
                _pct(row["required_km_out_of_scope"] / row["required_km_total"] * 100),
                _n(row["l_nodes"] - row["l_nodes_tourable"]),
            ]
        )
    parts.append("\n### 7.1 Requirement no closed tour can reach\n")
    parts.append(
        _table(
            ["Variant", "Required km", "Reachable", "Unreachable", "Share", "L-nodes lost"],
            rows,
        )
    )
    A = _by_variant(a)["A"]
    parts.append(
        "\nTwo different losses, with two different causes, belonging to two different stages:\n"
    )
    parts.append(
        _table(
            ["Cause", "Variant A", "Found by"],
            [
                ["Outside the base network's largest strong component — never entered L",
                 f"{_km(A['required_km_absent_from_l'])} km", "Stage 0"],
                ["Inside L but outside L's own strong component — a legal trap",
                 f"{_km(A['required_km_trapped_in_l'])} km", "Stage 1 trap audit"],
            ],
            numeric=False,
        )
    )
    parts.append(
        "\nThe first are hillside fragments and clip-edge stubs the base network could not\n"
        "reach in the first place. The second are arcs `L(G)` can enter but not leave, or\n"
        "leave but not enter, which Stage 1 already attributed to a cause — clip edge,\n"
        "mainline-entry rule, U-turn policy, turn restrictions, base topology. A closed\n"
        "circuit cannot contain either. They are reported rather than quietly absorbed into\n"
        "the coverage figure (CLAUDE.md rule 4), and together they are what the tour's\n"
        "capture time is short of Stage 2's.\n"
    )
    return _block(*parts)


def _spec(a: dict) -> str:
    return _block(
        "\n## 8. A correction to SPEC §4, now adopted\n",
        "SPEC v0.3 §4 labelled the fixed-orientation Chinese Postman result \"Stage A —\n"
        "Lower bound\", and I5 asserted total driving was at or above it. **That is the wrong\n"
        "direction.** Fixing an orientation for every narrow pair decides something the real\n"
        "problem is free to choose, which adds a constraint, which can only push the answer\n"
        "up. The result is a feasible solution and feasible solutions bound from above.\n",
        "SPEC v0.4 corrects both: §4 Stage A now brackets the optimum with a constructive\n"
        "upper bound and an LP lower bound, and I5 asserts total driving lies **within the\n"
        "bracket**. Stage 3 implements the corrected form, and the two numbers in the\n"
        "headline are the bracket I5 refers to.\n",
        "It matters beyond bookkeeping, and the failure it would have caused is not the\n"
        "obvious one. Under the original I5 the constructive result — "
        f"{_h(_by_variant(a)['A']['total_h'])} h — would\n"
        "have been treated as a floor. A **better** plan, anything between the true optimum\n"
        "and that figure, would have *failed* a test whose job was to catch plans that were\n"
        "too expensive: the invariant would have rejected exactly the improvements Stages 4\n"
        "and 5 exist to find. And every optimality gap in the project would have been\n"
        f"measured against {_h(_by_variant(a)['A']['total_h'])} h instead of "
        f"{_h(_by_variant(a)['A']['lower_bound_h'])} h.\n",
    )


# --------------------------------------------------------------------- gate


def _gate(a: dict) -> str:
    A = _by_variant(a)["A"]
    passed = {c["name"]: c["passed"] for c in A["invariants"]}
    described = (
        ("I1", "every arc ≥ min_passes; every narrow pair ≥ 1"),
        ("I2", "every consecutive manoeuvre is a legal edge of L"),
        ("I6", "every arc in the tour exists in the base network"),
        ("closed", "the circuit returns to its start by a legal manoeuvre"),
        ("lower_bounds", "the oriented lower bounds were delivered"),
        ("matches_flow", "the tour traverses each arc exactly as the flow paid for"),
    )
    rows = [
        [name, "PASS" if passed[name] else "**FAIL**", detail]
        for name, detail in described
        if name in passed
    ]
    return _block(
        "\n## 9. Gate\n",
        _table(["Invariant", "Result", "What it asserts"], rows, numeric=False),
        _table(
            ["Assertion", "Value"],
            [
                ["Upper ≥ lower, every variant",
                 " / ".join(f"{r['variant']}: {'yes' if r['total_h'] >= r['lower_bound_h'] else 'NO'}"
                            for r in a["variants"])],
                ["Tour total recomputed from its edges",
                 f"{_h(A['total_h'])} h = {_h(A['capture_h'])} + {_h(A['deadhead_h'])} + {_h(A['turn_h'])}"],
                ["Tour sha256", f"`{A.get('tour_sha256', '')[:16]}…`"],
                ["`network.gpkg` sha256", f"`{a['meta']['arcs_sha256'][:16]}…`"],
                ["Runtime", f"{_f(a['meta']['runtime_s'] / 60, 1)} min"],
            ],
            numeric=False,
        ),
        "\n### Non-goals honoured\n",
        "No zoning. No day-splitting. No depot legs. No variant chosen. The single tour is a\n"
        "bound and a sanity check, not a deliverable.\n",
    )
